select a.ymd, ifnull(sum(case a.scene when '0101' then a.balance else 0 end),0) 'sysRecharge', ifnull(sum(case a.scene when '0102' then a.balance else 0 end),0) 'sysReduce', ifnull(sum(case when a.scene = '0103' and a.refunded = 0 then a.balance else 0 end),0) 'withdraw', ifnull(sum(case when a.scene = '0103' and a.refunded = 1 then a.balance else 0 end),0) 'withdrawRefund', ifnull(sum(case a.scene when '0104' then a.balance else 0 end),0) 'recharge', ifnull(sum(case when a.scene = '0201' and a.refunded = 0 then a.balance else 0 end),0) 'pay', ifnull(sum(case when a.scene = '0201' and a.refunded = 1 then a.balance else 0 end),0) 'payRefund', ifnull(sum(case a.scene when '0301' then a.balance else 0 end),0) 'invest', ifnull(sum(case a.scene when '0401' then a.balance else 0 end),0) 'statics', ifnull(sum(case a.scene when '0402' then a.balance else 0 end),0) 'teamInvite', ifnull(sum(case a.scene when '0503' then a.balance else 0 end),0) 'publicRank', ifnull(sum(case when a.scene = '0601' and a.symbol = 'USDT' then a.balance else 0 end),0) 'exchange' from a_asset_flow a, u_member b
and a.uid = b.id and b.deleted = 0 and a.uid = #{uid} and b.email = #{account} and a.ymd between #{params.beginDay} and #{params.endDay}
group by a.ymd order by a.ymd desc
